<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{MusicComposition,SheetMusic};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class MusicLibraryController extends Controller{
 public function index(){return view('admin.music-library.index',['compositions'=>MusicComposition::orderBy('sort')->get(),'sheets'=>SheetMusic::orderBy('sort')->get()]);}
 public function storeComposition(Request $r){$d=$r->validate(['title'=>'required|max:255','composer'=>'nullable|max:255','performer'=>'nullable|max:255','instrument'=>'nullable|max:255','description'=>'nullable','audio_file'=>'required|file|max:51200|mimes:mp3,wav,ogg,m4a,aac','cover'=>'nullable|image|max:10240','sort'=>'nullable|integer|min:0']);$d['audio_file']=$r->file('audio_file')->store('music-library/audio','public');if($r->hasFile('cover'))$d['cover']=$r->file('cover')->store('music-library/covers','public');$d['sort']=$d['sort']??0;$d['is_published']=$r->boolean('is_published');MusicComposition::create($d);return back()->with('ok','Композиция добавлена');}
 public function destroyComposition(MusicComposition $composition){Storage::disk('public')->delete(array_filter([$composition->audio_file,$composition->cover]));$composition->delete();return back()->with('ok','Композиция удалена');}
 public function storeSheet(Request $r){$d=$r->validate(['title'=>'required|max:255','composer'=>'nullable|max:255','instrument'=>'nullable|max:255','level'=>'nullable|max:255','description'=>'nullable','file'=>'required|file|max:30720|mimes:pdf,jpg,jpeg,png,webp','preview'=>'nullable|image|max:10240','sort'=>'nullable|integer|min:0']);$d['file']=$r->file('file')->store('music-library/sheets','public');if($r->hasFile('preview'))$d['preview']=$r->file('preview')->store('music-library/previews','public');$d['sort']=$d['sort']??0;$d['is_published']=$r->boolean('is_published');SheetMusic::create($d);return back()->with('ok','Ноты добавлены');}
 public function destroySheet(SheetMusic $sheet){Storage::disk('public')->delete(array_filter([$sheet->file,$sheet->preview]));$sheet->delete();return back()->with('ok','Ноты удалены');}
}